 return subprocess.run(a,capture_output=True,text=True,timeout=t)
def active(s):
 return cmd(['systemctl','is-active',s+'.service'],8).stdout.strip()
def bots():
 r=cmd(['pm2','jlist'],14)
 if r.returncode:raise RuntimeError('PM2 inaccessible')
 return {a.get('name'):(a.get('pm2_env') or {}).get('status') for a in json.loads(r.stdout)}
protected=['pink-iptv-backend','pink-vpn','lowcost-europa','fadego-staging','pm2-root','nginx','postgresql@16-main','ssh']
baseline={k:active(k) for k in protected}
if any(v!='active' for v in baseline.values()):raise RuntimeError('Service preflight failed')
if any(bots().get(n)!='online' for n in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Telegram apps not online')
if not parent.is_dir() or parent.is_symlink() or not (parent/'iptvpn-bot').is_dir() or not (parent/'lowcost-europa').is_dir():
 raise RuntimeError('Canonical root / projects missing')
if not src.is_dir() or src.is_symlink() or dst.exists() or dst.is_symlink() or src.stat().st_dev!=parent.stat().st_dev:
 raise RuntimeError('PINK source/destination mismatch')
remote=cmd(['git','-C',str(src),'remote','get-url','origin'])
if remote.returncode or 'martaxi-boss/pink-iptv' not in remote.stdout:raise RuntimeError('Git origin mismatch')
git_before=cmd(['git','-C',str(src),'status','--porcelain','--untracked-files=no'],22)
if git_before.returncode:raise RuntimeError('Git local state inaccessible')
size=cmd(['du','-x','-s','-B1',str(src)],60)
if size.returncode:raise RuntimeError('PINK source size unavailable')
bytes_pre=int(size.stdout.split()[0]);inode=src.stat().st_ino
proof=src/'tests/device-proof'
if not proof.is_dir():raise RuntimeError('PINK device proof already organized missing')
proof_inode=proof.stat().st_ino
if not (src/'backend').is_dir() or not (src/'android').is_dir():raise RuntimeError('Expected backend or Android folder missing')
r=cmd(['systemctl','show','pink-iptv-backend.service','-p','MainPID','-p','WorkingDirectory','--no-pager'],13)
info=dict(line.split('=',1) for line in r.stdout.splitlines() if '=' in line)
pid=info.get('MainPID')
if info.get('WorkingDirectory')!=str(src/'backend') or not pid or not pid.isdigit() or int(pid)<=0:raise RuntimeError('PINK backend unit does not match source')
print('OLD_PINK_PHYSICAL_ROOT='+str(src))
print('NEW_CANONICAL_ROOT='+str(dst))
print('BYTES_TO_MOVE='+str(bytes_pre))
moved=False
try:
 src.rename(dst);moved=True;src.symlink_to(dst,target_is_directory=True)
 if not src.is_symlink() or src.resolve()!=dst or dst.stat().st_ino!=inode:raise RuntimeError('Old link/canonical root failed verification')
 if (dst/'tests/device-proof').stat().st_ino!=proof_inode:raise RuntimeError('Device proof inode changed')
 status=cmd(['git','-C',str(dst),'status','--porcelain','--untracked-files=no'],22)
 if status.returncode:
  print('GIT_AFTER_ERROR_CLASS='+status.stderr[:260].replace('\n',' '))
  raise RuntimeError('Git cannot inspect relocated checkout')
 if status.stdout!=git_before.stdout:
  print('GIT_BEFORE='+str(git_before.stdout.splitlines()[:14]))
  print('GIT_AFTER='+str(status.stdout.splitlines()[:14]))
  raise RuntimeError('Tracked local changes differ')
 now=cmd(['du','-x','-s','-B1',str(dst)],60)
 if now.returncode or int(now.stdout.split()[0])!=bytes_pre:raise RuntimeError('PINK size mismatch')
 backendpid=cmd(['systemctl','show','pink-iptv-backend.service','-p','MainPID','--no-pager'],12).stdout.strip()
 if backendpid!='MainPID='+pid:raise RuntimeError('PINK backend restarted')
 for name,v in baseline.items():
  if active(name)!=v:raise RuntimeError('Service status changed '+name)
 b=bots()
 if any(b.get(n)!='online' for n in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Telegram bot changed state')
except Exception:
 if src.is_symlink() and src.resolve()==dst:src.unlink()
 if moved and dst.exists() and not src.exists():dst.rename(src)
 print('PINK_ROOT_ROLLBACK=APPLIED')
 raise
print('CANONICAL_PINK_PATH='+str(dst))
print('COMPAT_SYMLINK='+str(src))
print('PINK_DIRECTORY_BYTES='+str(bytes_pre))
print('ANDROID_PROOFS_PRESERVED=YES')
print('LOCAL_GIT_CHANGES_PRESERVED='+str(len(git_before.stdout.splitlines())))
print('PINK_BACKEND_PID_PRESERVED='+pid)
print('PROTECTED_SYSTEMD_SERVICES=ACTIVE')
print('TELEGRAM_BOTS=ONLINE')
print('DISK_BYTES_FREED=0')
print('PINK_CANONICAL_MOVE=PASS')
